//! The class of each event of the catalog; generated by scripts/generate-event-classes.mjs from docs/spec/events.json; change the catalog and run the script.

/// The class of an event (docs/spec/logging.md#classes-and-policy).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Class {
    Lifecycle,
    Input,
    Call,
    Io,
    Frame,
}

impl Class {
    /// The classes in the order of the contract.
    pub const ALL: [Class; 5] = [
        Class::Lifecycle,
        Class::Input,
        Class::Call,
        Class::Io,
        Class::Frame,
    ];

    /// The name of the class in the line of an event and in the policy.
    pub fn as_str(self) -> &'static str {
        match self {
            Class::Lifecycle => "lifecycle",
            Class::Input => "input",
            Class::Call => "call",
            Class::Io => "io",
            Class::Frame => "frame",
        }
    }

    /// The class with the name, or `None` for a name that is not a class.
    pub fn parse(name: &str) -> Option<Class> {
        match name {
            "lifecycle" => Some(Class::Lifecycle),
            "input" => Some(Class::Input),
            "call" => Some(Class::Call),
            "io" => Some(Class::Io),
            "frame" => Some(Class::Frame),
            _ => None,
        }
    }
}

const FAMILIES: &[(&str, Class)] = &[
    ("host.record.", Class::Lifecycle),
    ("host.sampler.", Class::Call),
    ("host.trace.", Class::Call),
    ("native.record.", Class::Lifecycle),
    ("page.console.", Class::Lifecycle),
    ("page.record.", Class::Lifecycle),
    ("page.trace.", Class::Call),
    ("sidecar.record.", Class::Lifecycle),
    ("sok.record.", Class::Lifecycle),
];

/// The class that the catalog gives the event name, and `None` for a name the catalog does not declare.
pub fn class_of(name: &str) -> Option<Class> {
    let exact = match name {
        "host.app.event" => Some(Class::Lifecycle),
        "host.binding.call" => Some(Class::Call),
        "host.buffer.dropped" => Some(Class::Lifecycle),
        "host.call.peer-lost" => Some(Class::Call),
        "host.call.timeout" => Some(Class::Call),
        "host.crash.found" => Some(Class::Lifecycle),
        "host.endpoint.call" => Some(Class::Call),
        "host.input.relay" => Some(Class::Input),
        "host.log.index_rebuilt" => Some(Class::Lifecycle),
        "host.notification.event" => Some(Class::Lifecycle),
        "host.overlay.dropped" => Some(Class::Input),
        "host.panic" => Some(Class::Lifecycle),
        "host.project.removal_allowed" => Some(Class::Lifecycle),
        "host.relaunch.start" => Some(Class::Lifecycle),
        "host.run.unrecorded-end" => Some(Class::Lifecycle),
        "host.sidecar.connect" => Some(Class::Lifecycle),
        "host.sidecar.disconnect" => Some(Class::Lifecycle),
        "host.sidecar.exit" => Some(Class::Lifecycle),
        "host.sidecar.reply" => Some(Class::Io),
        "host.sidecar.request" => Some(Class::Io),
        "host.sidecar.restart-limit" => Some(Class::Lifecycle),
        "host.sidecar.start" => Some(Class::Lifecycle),
        "host.sidecar.write_wait" => Some(Class::Io),
        "host.stall" => Some(Class::Lifecycle),
        "host.stall.dump" => Some(Class::Lifecycle),
        "host.stall.resumed" => Some(Class::Lifecycle),
        "host.stall.sampled" => Some(Class::Lifecycle),
        "host.test.end" => Some(Class::Lifecycle),
        "host.test.start" => Some(Class::Lifecycle),
        "host.trace.call.late-reply" => Some(Class::Call),
        "host.trace.modal.stale-ready" => Some(Class::Call),
        "host.trace.sidecar.ready" => Some(Class::Call),
        "host.trace.sidecar.restart-reset" => Some(Class::Call),
        "host.trace.status.notify" => Some(Class::Call),
        "host.trace.view.presentation-abandoned" => Some(Class::Call),
        "host.trace.view.process-ready" => Some(Class::Call),
        "host.trace.view.process-request" => Some(Class::Call),
        "host.trace.view.responsive" => Some(Class::Call),
        "host.trace.view.unresponsive" => Some(Class::Call),
        "host.update.start" => Some(Class::Lifecycle),
        "host.window.event" => Some(Class::Lifecycle),
        "host.workspace.settings" => Some(Class::Lifecycle),
        "log.closed" => Some(Class::Lifecycle),
        "log.dropped" => Some(Class::Lifecycle),
        "log.gated" => Some(Class::Lifecycle),
        "log.migrated" => Some(Class::Lifecycle),
        "log.open" => Some(Class::Lifecycle),
        "log.policy" => Some(Class::Lifecycle),
        "log.pruned" => Some(Class::Lifecycle),
        "log.rotated" => Some(Class::Lifecycle),
        "native.app.activated" => Some(Class::Lifecycle),
        "native.app.deactivated" => Some(Class::Lifecycle),
        "native.app.hidden" => Some(Class::Lifecycle),
        "native.app.unhidden" => Some(Class::Lifecycle),
        "native.document.backforward_cleared" => Some(Class::Lifecycle),
        "native.input.callback" => Some(Class::Input),
        "native.input.key_down" => Some(Class::Input),
        "native.input.query" => Some(Class::Input),
        "native.input.report" => Some(Class::Input),
        "native.input.source_changed" => Some(Class::Input),
        "native.log.gated" => Some(Class::Lifecycle),
        "native.memory.pressure" => Some(Class::Lifecycle),
        "native.observe.counted" => Some(Class::Frame),
        "native.observe.delivered" => Some(Class::Input),
        "native.observe.failed" => Some(Class::Lifecycle),
        "native.observe.registered" => Some(Class::Lifecycle),
        "native.process.exit_timeout" => Some(Class::Lifecycle),
        "native.webview.input" => Some(Class::Lifecycle),
        "native.webview.process_ended" => Some(Class::Lifecycle),
        "native.window.deminiaturized" => Some(Class::Lifecycle),
        "native.window.first_responder" => Some(Class::Input),
        "native.window.key" => Some(Class::Lifecycle),
        "native.window.main" => Some(Class::Lifecycle),
        "native.window.miniaturized" => Some(Class::Lifecycle),
        "native.window.occlusion" => Some(Class::Lifecycle),
        "native.window.resign_key" => Some(Class::Lifecycle),
        "native.window.resign_main" => Some(Class::Lifecycle),
        "page.background.session" => Some(Class::Lifecycle),
        "page.call" => Some(Class::Call),
        "page.command" => Some(Class::Call),
        "page.input.shortcut.failed" => Some(Class::Input),
        "page.log.clock" => Some(Class::Lifecycle),
        "page.log.dropped" => Some(Class::Lifecycle),
        "page.log.gated" => Some(Class::Lifecycle),
        "page.overlay.dropped" => Some(Class::Input),
        "page.plugin.operation" => Some(Class::Call),
        "page.project.operation" => Some(Class::Call),
        "page.settings.change" => Some(Class::Call),
        "page.start" => Some(Class::Lifecycle),
        "page.tab.keep.changed" => Some(Class::Lifecycle),
        "page.tab.restore.failed" => Some(Class::Lifecycle),
        "page.tab.restored" => Some(Class::Lifecycle),
        "page.tab.session.dropped" => Some(Class::Lifecycle),
        "page.tab.session.orphan" => Some(Class::Lifecycle),
        "page.tab.session.stored" => Some(Class::Lifecycle),
        "page.tab.state.orphan" => Some(Class::Lifecycle),
        "page.tab.state.stored" => Some(Class::Lifecycle),
        "page.tab.unload.failed" => Some(Class::Lifecycle),
        "page.tab.unload.skipped" => Some(Class::Lifecycle),
        "page.tab.unloaded" => Some(Class::Lifecycle),
        "page.trace.declared-ui.snapshot.skipped" => Some(Class::Call),
        "page.trace.modal.answer" => Some(Class::Call),
        "page.trace.picker.close" => Some(Class::Call),
        "page.trace.surface.mount" => Some(Class::Call),
        "page.update.operation" => Some(Class::Call),
        "page.view.shortcut-table-missing" => Some(Class::Input),
        "page.window.operation" => Some(Class::Call),
        "sok.command" => Some(Class::Call),
        "sok.panic" => Some(Class::Lifecycle),
        "sok.replay.divergence" => Some(Class::Frame),
        _ => None,
    };
    if exact.is_some() {
        return exact;
    }
    for (prefix, class) in FAMILIES {
        if let Some(tail) = name.strip_prefix(prefix)
            && !tail.is_empty()
            && tail.bytes().all(is_tail_byte)
        {
            return Some(*class);
        }
    }
    None
}

/// A byte that a placeholder of a family stands for: `a-z`, `0-9`, `_` or `.`.
fn is_tail_byte(byte: u8) -> bool {
    byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'_' || byte == b'.'
}
